const previousDigest = $('Load checkpoint').first().json.previousDigest ?? null;
const raw = $env.CATALOG_ITEMS_JSON;
if (!raw || String(raw).trim() === '') {
  throw new Error('CATALOG_ITEMS_JSON env is empty. Set a JSON array of { externalVariantId, sku } (max 100).');
}
let items;
try {
  items = JSON.parse(String(raw));
} catch (error) {
  throw new Error('CATALOG_ITEMS_JSON is not valid JSON');
}
if (!Array.isArray(items) || items.length === 0) {
  throw new Error('CATALOG_ITEMS_JSON must be a non-empty array');
}
if (items.length > 100) {
  throw new Error('CATALOG_ITEMS_JSON exceeds max batch 100');
}
const workspaceKey = $env.SKU_API_WORKSPACE || 'synarava-shop';
const correlationId = `n8n-catalog-audit-${Date.now()}`;
return [{
  json: {
    workspaceKey,
    previousDigest,
    correlationId,
    body: {
      items: items.map((row) => ({
        externalVariantId: String(row.externalVariantId || ''),
        sku: row.sku == null ? '' : String(row.sku),
      })),
      previousDigest,
      correlationId,
    },
  },
}];

