const audit = $('POST audit/catalog').first().json;
if (!audit || typeof audit.digest !== 'string') {
  throw new Error('audit response missing digest');
}
const staticData = $getWorkflowStaticData('global');
staticData.previousDigest = audit.digest;
staticData.updatedAt = new Date().toISOString();
staticData.lastCorrelationId = audit.correlationId ?? null;
staticData.lastDeviationCount = audit.deviationCount ?? 0;
return [{
  json: {
    ok: true,
    previousDigest: staticData.previousDigest,
    shouldNotify: audit.shouldNotify === true,
    deviationCount: audit.deviationCount ?? 0,
  },
}];

